INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-001', 'What is a budget?', 'Budgeting', 'A budget is a plan for your money. You list the money you expect to receive (income) and decide in advance how much will go to each kind of spending and to savings.
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-002', 'The 50/30/20 rule', 'Budgeting', 'A simple starting point for splitting income:
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-003', 'Pay yourself first', 'Saving', 'Move money into savings as soon as you receive it, instead of saving "whatever is left" at the end of the month – usually nothing is left!
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-004', 'Building an emergency fund', 'Saving', 'An emergency fund is money kept aside for surprises: a broken phone screen, a medical bill or an unexpected trip home.
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-005', 'Understanding your income', 'Income', 'Income is any money you receive: allowance, scholarships, internship stipends, part-time jobs or gifts.
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-006', 'Needs vs. wants', 'Expenses', 'Necessary expenses (needs) are things you must pay for to live and study: food, transport to class, required books, rent and basic bills.
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-007', 'Spotting small leaks', 'Expenses', 'Small, frequent purchases are the easiest way to overspend without noticing: snacks, delivery fees, in-app purchases and unused subscriptions.
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-008', 'Planning for study requirements', 'Requirements', 'Every term brings required costs: textbooks, lab fees, printing, software and exam registrations. They are easy to forget because they are not monthly.
INSERT INTO LearningContent (ContentId, Title, Topic, Body, DifficultyLevel, ImageUrl, IsActive) VALUES ('learn-009', 'Setting SMART savings goals', 'Saving', 'Good goals are Specific, Measurable, Achievable, Relevant and Time-bound.
INSERT INTO Notifications (NotificationId, UserId, Title, Message, Type, ReadStatus, CreatedAt) VALUES ('notif-demo-001', 'user-student-0001', 'Welcome to PennyPal!', 'Start by adding your income, then set a monthly budget to get alerts before you overspend.', 'system', 0, '2026-09-24T14:43:53.874524');
INSERT INTO SupportQueries (QueryId, UserId, Subject, Message, Status, AdminResponse, SubmittedOn) VALUES ('query-demo-001', 'user-student-0001', 'How do I change my currency?', 'I moved abroad for my exchange semester. Can I show amounts in EUR?', 'resolved', 'Yes! Open More > Profile & settings and choose EUR under Currency.', '2026-09-24T14:43:53.874524');
